from pathlib import Path
import lzma,gzip
MAX_VARS=150000
MAX_CLAUSES=1000000
MAX_LITS=6000000
root=Path('benchmarks/sat-competition-2024-main-benchmarks')
inst=sorted([p for p in root.rglob('*') if p.is_file() and p.name.lower().endswith(('.cnf','.cnf.xz','.cnf.gz'))])[:100]
fit=[]
over=[]
for p in inst:
    if p.name.lower().endswith('.cnf'):
        f=open(p,'rt',errors='ignore')
    elif p.name.lower().endswith('.cnf.xz'):
        f=lzma.open(p,'rt',errors='ignore')
    else:
        f=gzip.open(p,'rt',errors='ignore')
    dv=dc=None
    with f:
        for line in f:
            s=line.strip()
            if not s or s[0] in 'cC':
                continue
            if s[0] in 'pP':
                parts=s.split()
                if len(parts)>=4 and parts[1].lower()=='cnf':
                    dv=int(parts[2]);dc=int(parts[3])
                break
            else:
                break
    if dv is None:
        continue
    if dv<=MAX_VARS and dc<=MAX_CLAUSES and 2*dc<=MAX_LITS:
        fit.append((p.name,dv,dc))
    else:
        over.append((p.name,dv,dc))
print('fit',len(fit),'over',len(over))
print('fit examples:')
for t in fit[:20]:
    print(t)
print('over examples:')
for t in over[:20]:
    print(t)
